from datetime import datetime, timedelta, timezone

SESSION_TTL = timedelta(hours=8)


def parse_timestamp(text):
    """Parse ISO 8601 text into an aware datetime in UTC. Text with no offset was written by our own servers: it is UTC."""
    return datetime.fromisoformat(text)


def session_ends_at(started_at):
    """When the session that started at `started_at` (ISO text) ends, as an aware UTC datetime."""
    return parse_timestamp(started_at) + SESSION_TTL


def is_expired(started_at, now):
    """True once `now`, an aware UTC datetime, has reached the end of the session."""
    return now >= session_ends_at(started_at)


def seconds_left(started_at, now):
    """Whole seconds until the session ends; 0 once it has."""
    return max(0, int((session_ends_at(started_at) - now).total_seconds()))

